void backtrack(vector<int>& path, vector<bool>& used, vector<int>& nums,
               vector<vector<int>>& res) {
    if ((int)path.size() == (int)nums.size()) { res.push_back(path); return; }
    for (int i = 0; i < (int)nums.size(); i++) {
        if (used[i]) continue;
        used[i] = true; path.push_back(nums[i]);
        backtrack(path, used, nums, res);
        used[i] = false; path.pop_back(); // RESTORE STATE
    }
}

Union-Find (DSU).boilerplate:
class DSU {
    vector<int> parent, rank_;
public:
    DSU(int n) : parent(n), rank_(n, 0) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]); // path compression
        return parent[x];
    }
    bool unite(int x, int y) {
        int px = find(x), py = find(y);
        if (px == py) return false;
        if (rank_[px] < rank_[py]) swap(px, py);
        parent[py] = px;
        if (rank_[px] == rank_[py]) rank_[px]++;
        return true;
    }
    bool connected(int x, int y) { return find(x) == find(y); }
};

// Detect cycle
bool hasCycle(int n, vector<vector<int>>& edges) {
    DSU dsu(n);
    for (auto& e : edges)
        if (!dsu.unite(e[0], e[1])) return true;
    return false;
}

Topological Sort (Kahn's BFS).boilerplate:
// Kahn's Algorithm — O(V + E)
vector<int> topoSort(int n, vector<vector<int>>& edges) {
    vector<vector<int>> adj(n);
    vector<int> indegree(n, 0);
    for (auto& e : edges) { adj[e[0]].push_back(e[1]); indegree[e[1]]++; }
    queue<int> q;
    for (int i = 0; i < n; i++) if (indegree[i] == 0) q.push(i);
    vector<int> order;
    while (!q.empty()) {
        int node = q.front(); q.pop();
        order.push_back(node);
        for (int nb : adj[node])
            if (--indegree[nb] == 0) q.push(nb);
    }
    return (int)order.size() == n ? order : vector<int>{}; // empty = cycle
}

bool canFinish(int n, vector<vector<int>>& prereqs) {
    return topoSort(n, prereqs).size() == (size_t)n;
}

