class Trie {
    TrieNode* root;
public:
    Trie() : root(new TrieNode()) {}

    void insert(const string& w) {
        TrieNode* node = root;
        for (char c : w) {
            int i = c - 'a';
            if (!node->ch[i]) node->ch[i] = new TrieNode();
            node = node->ch[i];
        }
        node->isEnd = true;
    }

    bool search(const string& w) {
        TrieNode* node = root;
        for (char c : w) {
            int i = c - 'a';
            if (!node->ch[i]) return false;
            node = node->ch[i];
        }
        return node->isEnd;
    }

    bool startsWith(const string& prefix) {
        TrieNode* node = root;
        for (char c : prefix) {
            int i = c - 'a';
            if (!node->ch[i]) return false;
            node = node->ch[i];
        }
        return true;
    }
};

