class MedianFinder {
    priority_queue<int> maxH;                          // max-heap
    priority_queue<int,vector<int>,greater<int>> minH; // min-heap
public:
    void addNum(int num) {
        maxH.push(num);
        if (!minH.empty() && maxH.top() > minH.top()) {
            minH.push(maxH.top()); maxH.pop();
        }
        if ((int)maxH.size() > (int)minH.size() + 1) {
            minH.push(maxH.top()); maxH.pop();
        } else if ((int)minH.size() > (int)maxH.size()) {
            maxH.push(minH.top()); minH.pop();
        }
    }
    double findMedian() {
        if (maxH.size() == minH.size())
            return (maxH.top() + minH.top()) / 2.0;
        return maxH.top();
    }
};

K-way Merge.boilerplate:
// K-way Merge — O(n log k)
vector<int> mergeKSorted(vector<vector<int>>& arrays) {
    using T = tuple<int,int,int>; // {val, arr_idx, elem_idx}
    priority_queue<T, vector<T>, greater<T>> minH;
    for (int i = 0; i < (int)arrays.size(); i++)
        if (!arrays[i].empty()) minH.push({arrays[i][0], i, 0});
    vector<int> res;
    while (!minH.empty()) {
        auto [val, ai, ei] = minH.top(); minH.pop();
        res.push_back(val);
        if (ei + 1 < (int)arrays[ai].size())
            minH.push({arrays[ai][ei+1], ai, ei+1});
    }
    return res;
}

// Merge k sorted linked lists
struct ListNode { int val; ListNode* next; };
ListNode* mergeKLists(vector<ListNode*>& lists) {
    using P = pair<int,ListNode*>;
    priority_queue<P, vector<P>, greater<P>> minH;
    for (auto* l : lists) if (l) minH.push({l->val, l});
    ListNode dummy(0); ListNode* tail = &dummy;
    while (!minH.empty()) {
        auto [v, node] = minH.top(); minH.pop();
        tail->next = node; tail = tail->next;
        if (node->next) minH.push({node->next->val, node->next});
    }
    return dummy.next;
}

