// Combination Sum (elements reusable)
void combinationSum(vector<int>& cands, int target, int start,
                    vector<int>& path, vector<vector<int>>& res) {
    if (target == 0) { res.push_back(path); return; }
    for (int i = start; i < (int)cands.size(); i++) {
        if (cands[i] > target) break; // prune — sort first!
        path.push_back(cands[i]);
        combinationSum(cands, target - cands[i], i, path, res); // i, not i+1
        path.pop_back();
    }
}

