// Interval DP — O(n^3)
// dp[i][j] = answer for subproblem [i..j]
// Key: iterate by increasing length, choose 'last pivot k'

// Burst Balloons
int maxCoins(vector<int>& nums) {
    nums.insert(nums.begin(), 1); nums.push_back(1);
    int n = nums.size();
    vector<vector<int>> dp(n, vector<int>(n, 0));
    for (int len = 2; len < n; len++) {
        for (int i = 0; i + len < n; i++) {
            int j = i + len;
            for (int k = i+1; k < j; k++) // k = last balloon burst in (i,j)
                dp[i][j] = max(dp[i][j],
                    dp[i][k] + nums[i]*nums[k]*nums[j] + dp[k][j]);
        }
    }
    return dp[0][n-1];
}

