// Bit Manipulation Toolkit
bool isBitSet(int n, int i)  { return (n >> i) & 1; }
int setBit(int n, int i)     { return n | (1 << i); }
int clearBit(int n, int i)   { return n & ~(1 << i); }
int toggleBit(int n, int i)  { return n ^ (1 << i); }
bool isPow2(int n)           { return n > 0 && (n & (n-1)) == 0; }

// Count set bits (Brian Kernighan)
int popcount(int n) {
    int cnt = 0;
    while (n) { n &= (n - 1); cnt++; }
    return cnt;
}

// Single number (XOR trick: a^a=0, a^0=a)
int singleNumber(vector<int>& nums) {
    int res = 0;
    for (int n : nums) res ^= n;
    return res;
}

// Two non-repeating numbers
pair<int,int> singleNumberIII(vector<int>& nums) {
    int xorAll = 0;
    for (int n : nums) xorAll ^= n;
    int diffBit = xorAll & (-xorAll); // isolate rightmost set bit
    int a = 0, b = 0;
    for (int n : nums)
        (n & diffBit ? a : b) ^= n;
    return {a, b};
}
